import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor gelu_cute_forward(torch::Tensor x);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

__device__ __forceinline__ float gelu_scalar(float x) {
    constexpr float k0 = 0.7978845608028654f; // sqrt(2/pi)
    constexpr float k1 = 0.044715f;
    float x3 = x * x * x;
    return 0.5f * x * (1.0f + tanhf(k0 * (x + k1 * x3)));
}

template <int THREADS, int ITEMS>
__global__ void gelu_kernel_cute(const float4* __restrict__ Xp,
                                  float4* __restrict__ Yp,
                                  int N4)
{
    constexpr int TILE = THREADS * ITEMS;

    Tensor mX = make_tensor(make_gmem_ptr(Xp), make_shape(N4), make_stride(Int<1>{}));
    Tensor mY = make_tensor(make_gmem_ptr(Yp), make_shape(N4), make_stride(Int<1>{}));

    auto cta_tiler = make_shape(Int<TILE>{});
    auto cta_coord = make_coord(blockIdx.x);

    Tensor gX = local_tile(mX, cta_tiler, cta_coord);
    Tensor gY = local_tile(mY, cta_tiler, cta_coord);

    auto tLayout = make_layout(make_shape(Int<THREADS>{}));

    Tensor tXgX = local_partition(gX, tLayout, threadIdx.x);
    Tensor tYgY = local_partition(gY, tLayout, threadIdx.x);

    int base = blockIdx.x * TILE;

    #pragma unroll
    for (int i = 0; i < ITEMS; ++i) {
        int idx = base + threadIdx.x + i * THREADS;
        if (idx < N4) {
            float4 v = tXgX(i);
            float4 o;
            o.x = gelu_scalar(v.x);
            o.y = gelu_scalar(v.y);
            o.z = gelu_scalar(v.z);
            o.w = gelu_scalar(v.w);
            tYgY(i) = o;
        }
    }
}

__global__ void gelu_tail_kernel(const float* __restrict__ X,
                                  float* __restrict__ Y,
                                  int start, int N)
{
    int idx = start + blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < N) {
        Y[idx] = gelu_scalar(X[idx]);
    }
}

torch::Tensor gelu_cute_forward(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "x must be CUDA");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");

    auto x_c = x.contiguous();
    auto y = torch::empty_like(x_c);

    int64_t N = x_c.numel();
    int64_t N4 = N / 4;
    int64_t rem_start = N4 * 4;

    const float* x_ptr = x_c.data_ptr<float>();
    float* y_ptr = y.data_ptr<float>();

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    constexpr int THREADS = 256;
    constexpr int ITEMS = 8;
    constexpr int TILE = THREADS * ITEMS;

    if (N4 > 0) {
        const float4* x4 = reinterpret_cast<const float4*>(x_ptr);
        float4* y4 = reinterpret_cast<float4*>(y_ptr);

        int grid = (int)((N4 + TILE - 1) / TILE);
        gelu_kernel_cute<THREADS, ITEMS><<<grid, THREADS, 0, stream>>>(
            x4, y4, (int)N4);

        auto err = cudaGetLastError();
        TORCH_CHECK(err == cudaSuccess, "gelu_kernel_cute launch failed: ", cudaGetErrorString(err));
    }

    int64_t rem = N - rem_start;
    if (rem > 0) {
        int threads = 32;
        int grid = (int)((rem + threads - 1) / threads);
        gelu_tail_kernel<<<grid, threads, 0, stream>>>(
            x_ptr, y_ptr, (int)rem_start, (int)N);

        auto err = cudaGetLastError();
        TORCH_CHECK(err == cudaSuccess, "gelu_tail_kernel launch failed: ", cudaGetErrorString(err));
    }

    return y;
}
"""

gelu_ext = load_inline(
    name="cute_gelu_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["gelu_cute_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    GELU (tanh approximation) implemented with a single fused CUDA/CUTE kernel.
    """
    def __init__(self) -> None:
        super(ModelNew, self).__init__()
        self._ext = gelu_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.gelu_cute_forward(x)

